    if (!converted) {
      throw new Error("\uC720\uD6A8\uD558\uC9C0 \uC54A\uC740 \uC74C\uB825 \uB0A0\uC9DC\uC785\uB2C8\uB2E4. \uC5F0\uB3C4\uC640 \uC6D4, \uC724\uB2EC \uC5EC\uBD80\uB97C \uD655\uC778\uD574 \uC8FC\uC138\uC694.");
    }
