  const activePillars = [yearPillar, monthPillar, dayPillar, ...hourPillar ? [hourPillar] : []];
  const rawCounts = { wood: 0, fire: 0, earth: 0, metal: 0, water: 0 };
  const weighted = { wood: 0, fire: 0, earth: 0, metal: 0, water: 0 };
