    lagnaTrait: "\uCC28\uBD84\uD558\uACE0 \uBB35\uC9C1\uD55C \uC2E0\uB8B0\uAC10\uC744 \uD48D\uAE30\uBA70, \uB9D0\uD22C\uC640 \uBD84\uC704\uAE30\uC5D0\uC11C \uB2E8\uC815\uD55C \uC5EC\uC720\uC640 \uC2EC\uBBF8\uC548\uC774 \uB290\uAEF4\uC9D1\uB2C8\uB2E4.",
