    moonTrait: "\uAD00\uCC30\uB825\uC774 \uC608\uB9AC\uD558\uACE0 \uC8FC\uBCC0\uACFC \uC77C\uC815\uC774 \uB2E8\uC815\uD558\uAC8C \uC815\uB3C8\uB418\uC5B4 \uC788\uC744 \uB54C \uB9C8\uC74C\uC774 \uAC00\uC7A5 \uD3B8\uC548\uD569\uB2C8\uB2E4. \uC2E4\uC6A9\uC801\uC778 \uB3C4\uC6C0\uC744 \uC904 \uB54C \uAE4A\uC740 \uBCF4\uB78C\uC744 \uB290\uB08D\uB2C8\uB2E4.",
