var DEG2RAD = Math.PI / 180;
var RAD2DEG = 180 / Math.PI;
function norm360(deg) {
  const r = deg % 360;
  return r < 0 ? r + 360 : r;
}
function solveKepler(Mdeg, e) {
  const M = norm360(Mdeg) * DEG2RAD;
  let E = M + e * Math.sin(M) * (1 + e * Math.cos(M));
  for (let iter = 0; iter < 6; iter++) {
    const dE = (E - e * Math.sin(E) - M) / (1 - e * Math.cos(E));
    E -= dE;
  }
  return E;
}
function getJulianDayFromUtc(year, month, day, hour, minute) {
  const utcMs = Date.UTC(year, month - 1, day, hour, minute) - 9 * 36e5;
  return utcMs / 864e5 + 24405875e-1;
}
function computeLahiriAyanamsa(jd) {
  const yearsFromJ2000 = (jd - 2451545) / 365.25;
  return 23.8530556 + 0.0139697128 * yearsFromJ2000;
}
function computeHeliocentric(el) {
  const E = solveKepler(el.M, el.e);
  const xv = el.a * (Math.cos(E) - el.e);
  const yv = el.a * Math.sqrt(1 - el.e * el.e) * Math.sin(E);
  const v = Math.atan2(yv, xv);
  const r = Math.hypot(xv, yv);
  const N = norm360(el.N) * DEG2RAD;
  const i = el.i * DEG2RAD;
  const vw = v + norm360(el.w) * DEG2RAD;
  const x = r * (Math.cos(N) * Math.cos(vw) - Math.sin(N) * Math.sin(vw) * Math.cos(i));
  const y = r * (Math.sin(N) * Math.cos(vw) + Math.cos(N) * Math.sin(vw) * Math.cos(i));
  const z = r * (Math.sin(vw) * Math.sin(i));
  return { x, y, z };
}
function calculateSiderealLongitudes(jd) {
  const d = jd - 24515435e-1;
  const ayanamsa = computeLahiriAyanamsa(jd);
  const wSun = 282.9404 + 470935e-10 * d;
  const eSun = 0.016709 - 1151e-12 * d;
  const MSun = norm360(356.047 + 0.9856002585 * d);
  const ESun = solveKepler(MSun, eSun);
  const xvSun = Math.cos(ESun) - eSun;
  const yvSun = Math.sqrt(1 - eSun * eSun) * Math.sin(ESun);
  const vSun = Math.atan2(yvSun, xvSun) * RAD2DEG;
  const rSun = Math.hypot(xvSun, yvSun);
  const sunLon = norm360(vSun + wSun);
  const xs = rSun * Math.cos(sunLon * DEG2RAD);
  const ys = rSun * Math.sin(sunLon * DEG2RAD);
  const Ls = norm360(MSun + wSun);
  const NMoon = norm360(125.1228 - 0.0529538083 * d);
  const iMoon = 5.1454;
  const wMoon = norm360(318.0634 + 0.1643573223 * d);
  const aMoon = 60.2666;
  const eMoon = 0.0549;
  const MMoon = norm360(115.3654 + 13.0649929509 * d);
  const moonPos = computeHeliocentric({
    N: NMoon,
    i: iMoon,
    w: wMoon,
    a: aMoon,
    e: eMoon,
    M: MMoon
  });
  let moonLon = norm360(Math.atan2(moonPos.y, moonPos.x) * RAD2DEG);
  const Lm = norm360(NMoon + wMoon + MMoon);
  const D = norm360(Lm - Ls);
  const F = norm360(Lm - NMoon);
  const moonPerturb = -1.274 * Math.sin((MMoon - 2 * D) * DEG2RAD) + 0.658 * Math.sin(2 * D * DEG2RAD) - 0.186 * Math.sin(MSun * DEG2RAD) - 0.059 * Math.sin((2 * MMoon - 2 * D) * DEG2RAD) - 0.057 * Math.sin((MMoon - 2 * D + MSun) * DEG2RAD) + 0.053 * Math.sin((MMoon + 2 * D) * DEG2RAD) + 0.046 * Math.sin((2 * D - MSun) * DEG2RAD) + 0.041 * Math.sin((MMoon - MSun) * DEG2RAD) - 0.035 * Math.sin(D * DEG2RAD) - 0.031 * Math.sin((MMoon + MSun) * DEG2RAD) - 0.015 * Math.sin((2 * F - 2 * D) * DEG2RAD) + 0.011 * Math.sin((MMoon - 4 * D) * DEG2RAD);
  moonLon = norm360(moonLon + moonPerturb);
  const mercPos = computeHeliocentric({
    N: 48.3313 + 324587e-10 * d,
    i: 7.0047 + 5e-8 * d,
    w: 29.1241 + 101444e-10 * d,
    a: 0.387098,
    e: 0.205635 + 559e-12 * d,
    M: 168.6562 + 4.0923344368 * d
  });
  const mercuryLon = norm360(Math.atan2(mercPos.y + ys, mercPos.x + xs) * RAD2DEG);
  const venusPos = computeHeliocentric({
    N: 76.6799 + 24659e-9 * d,
    i: 3.3946 + 275e-10 * d,
    w: 54.891 + 138374e-10 * d,
    a: 0.72333,
    e: 6773e-6 - 1302e-12 * d,
    M: 48.0052 + 1.6021302244 * d
  });
  const venusLon = norm360(Math.atan2(venusPos.y + ys, venusPos.x + xs) * RAD2DEG);
  const marsPos = computeHeliocentric({
    N: 49.5574 + 211081e-10 * d,
    i: 1.8497 - 178e-10 * d,
    w: 286.5016 + 292961e-10 * d,
    a: 1.523688,
    e: 0.093405 + 2516e-12 * d,
    M: 18.6021 + 0.5240207766 * d
  });
  const marsLon = norm360(Math.atan2(marsPos.y + ys, marsPos.x + xs) * RAD2DEG);
  const Mj = norm360(19.895 + 0.0830853001 * d);
  const Ms = norm360(316.967 + 0.0334442282 * d);
  const jupPos = computeHeliocentric({
    N: 100.4542 + 276854e-10 * d,
    i: 1.303 - 1557e-10 * d,
    w: 273.8777 + 164505e-10 * d,
    a: 5.20256,
    e: 0.048498 + 4469e-12 * d,
    M: Mj
  });
  const jupPert = -0.332 * Math.sin((2 * Mj - 5 * Ms - 67.6) * DEG2RAD) - 0.056 * Math.sin((2 * Mj - 2 * Ms + 21) * DEG2RAD) + 0.042 * Math.sin((3 * Mj - 5 * Ms + 21) * DEG2RAD) - 0.036 * Math.sin((Mj - 2 * Ms) * DEG2RAD) + 0.022 * Math.cos((Mj - Ms) * DEG2RAD);
  const jupiterLon = norm360(Math.atan2(jupPos.y + ys, jupPos.x + xs) * RAD2DEG + jupPert);
  const satPos = computeHeliocentric({
    N: 113.6634 + 23898e-9 * d,
    i: 2.4886 - 1081e-10 * d,
    w: 339.3939 + 297661e-10 * d,
    a: 9.55475,
    e: 0.055546 - 9499e-12 * d,
    M: Ms
  });
  const satPert = 0.812 * Math.sin((2 * Mj - 5 * Ms - 67.6) * DEG2RAD) - 0.229 * Math.cos((2 * Mj - 4 * Ms - 2) * DEG2RAD) + 0.119 * Math.sin((Mj - 2 * Ms - 3) * DEG2RAD) + 0.046 * Math.sin((2 * Mj - 6 * Ms - 69) * DEG2RAD);
  const saturnLon = norm360(Math.atan2(satPos.y + ys, satPos.x + xs) * RAD2DEG + satPert);
  const T = (jd - 2451545) / 36525;
  const gmst = norm360(280.46061837 + 360.98564736629 * (jd - 2451545) + 387933e-9 * T * T);
  const lstRad = norm360(gmst + 126.978) * DEG2RAD;
  const epsRad = (23.439291 - 0.0130042 * T) * DEG2RAD;
  const latRad = 37.5665 * DEG2RAD;
  const ascLon = norm360(
    Math.atan2(
      Math.cos(lstRad),
      -(Math.sin(lstRad) * Math.cos(epsRad) + Math.tan(latRad) * Math.sin(epsRad))
    ) * RAD2DEG
  );
  const rahuSid = norm360(NMoon - ayanamsa);
  const ketuSid = norm360(rahuSid + 180);
  return {
    ayanamsa,
    sun: norm360(sunLon - ayanamsa),
    moon: norm360(moonLon - ayanamsa),
    mercury: norm360(mercuryLon - ayanamsa),
    venus: norm360(venusLon - ayanamsa),
    mars: norm360(marsLon - ayanamsa),
    jupiter: norm360(jupiterLon - ayanamsa),
    saturn: norm360(saturnLon - ayanamsa),
    rahu: rahuSid,
    ketu: ketuSid,
    lagna: norm360(ascLon - ayanamsa)
  };
}
function formatDegree(degInSign) {
  const whole = Math.floor(degInSign);
  const mins = Math.floor((degInSign - whole) * 60);
  return `${String(whole).padStart(2, "0")}\xB0 ${String(mins).padStart(2, "0")}'`;
}
function getNakshatraFromLongitude(siderealLon) {
  const span = 360 / 27;
  const lon = norm360(siderealLon);
  const index = Math.floor(lon / span) % 27;
  const offset = lon - index * span;
  const fractionElapsed = offset / span;
  const pada = Math.min(4, Math.floor(fractionElapsed * 4) + 1);
  return {
    info: NAKSHATRAS[index],
    pada,
    fractionElapsed
  };
}
function buildGrahaPlacement(id, nameKo, sanskritKo, shortLabel, symbol, domainKo, longitude, baseRashiIndex) {
  const lon = norm360(longitude);
  const signIdx = Math.floor(lon / 30) % 12;
  const sign = VEDIC_RASHIS[signIdx];
  const degreeInSign = lon % 30;
  const nak = getNakshatraFromLongitude(lon);
  const house = (signIdx - baseRashiIndex + 12) % 12 + 1;
  const houseDomain = HOUSE_DOMAINS[house - 1];
  let interpretation = "";
  switch (id) {
    case "moon":
      interpretation = `${sign.moonTrait} \uCD9C\uC0DD \uB2EC \uB098\uD06C\uC0E4\uD2B8\uB77C '${nak.info.nameKo}'(${nak.pada}\uD30C\uB2E4)\uC758 \uACB0\uC774 \uB354\uD574\uC838, ${nak.info.description}`;
      break;
    case "sun":
      interpretation = `${sign.sunTrait} ${houseDomain} \uC601\uC5ED\uC5D0\uC11C \uC2A4\uC2A4\uB85C\uC758 \uBA85\uBD84\uACFC \uC874\uC7AC\uAC10\uC744 \uC138\uC6B0\uB824\uB294 \uC758\uC9C0\uAC00 \uB610\uB837\uD558\uAC8C \uC791\uB3D9\uD569\uB2C8\uB2E4.`;
      break;
    case "lagna":
      interpretation = `${sign.lagnaTrait} \uB77C\uADF8\uB098 \uB098\uD06C\uC0E4\uD2B8\uB77C '${nak.info.nameKo}'\uC758 \uBD84\uC704\uAE30\uAC00 \uCCAB\uC778\uC0C1\uACFC \uC0B6\uC758 \uAE30\uBCF8 \uB9AC\uB4EC\uC5D0 \uC790\uC5F0\uC2A4\uB808 \uC2A4\uBA70\uB4ED\uB2C8\uB2E4.`;
      break;
    case "venus":
      interpretation = `${sign.venusTrait} ${houseDomain} \uC601\uC5ED\uC744 \uD1B5\uD574 \uC77C\uC0C1\uC758 \uBBF8\uAC10, \uC778\uC5F0\uC758 \uAE30\uC068, \uD48D\uC694\uC758 \uAC10\uAC01\uC774 \uD53C\uC5B4\uB0A9\uB2C8\uB2E4.`;
      break;
    case "mars":
      interpretation = `${sign.marsTrait} ${houseDomain} \uC601\uC5ED\uC5D0\uC11C \uC2B9\uBD80\uC695\uACFC \uC2E4\uD589\uB825\uC774 \uC9D1\uC911\uC801\uC73C\uB85C \uBC1C\uD718\uB429\uB2C8\uB2E4.`;
      break;
    case "mercury":
      interpretation = `\uBD80\uB2E4(\uC218\uC131)\uAC00 ${sign.sanskritKo}(${sign.nameKo}) \xB7 ${houseDomain}\uC5D0 \uB193\uC5EC \uC0AC\uACE0\uC640 \uB9D0\uC528\uC5D0 '${sign.keyword}'\uC758 \uACB0\uC774 \uBC30\uC5B4\uB0A9\uB2C8\uB2E4. \uC815\uBCF4\uB97C \uBD84\uC11D\uD558\uACE0 \uC0AC\uB78C\uACFC \uAC70\uB798\xB7\uC18C\uD1B5\uD560 \uB54C \uBA85\uCF8C\uD55C \uC2E4\uBB34 \uAC10\uAC01\uC774 \uBE5B\uB0A9\uB2C8\uB2E4.`;
      break;
    case "jupiter":
      interpretation = `\uC9C0\uD61C\uC640 \uD655\uC7A5\uC758 \uAD6C\uB8E8(\uBAA9\uC131)\uAC00 ${sign.sanskritKo}(${sign.nameKo}) \xB7 ${houseDomain}\uC5D0 \uC790\uB9AC\uD588\uC2B5\uB2C8\uB2E4. '${sign.keyword}'\uC640 \uB9DE\uB2FF\uC740 \uD0DC\uB3C4\uB85C \uC138\uC0C1\uACFC \uB098\uB20C\uC218\uB85D \uADC0\uC778\uACFC \uBC30\uC6C0\uC758 \uBCF5\uC774 \uCEE4\uC9D1\uB2C8\uB2E4.`;
      break;
    case "saturn":
      interpretation = `\uC5C5\uBCF4\uC640 \uC131\uC219\uC758 \uC0E4\uB2C8(\uD1A0\uC131)\uAC00 ${sign.sanskritKo}(${sign.nameKo}) \xB7 ${houseDomain}\uC5D0 \uB193\uC5EC \uC788\uC2B5\uB2C8\uB2E4. \uCD08\uBC18\uC5D0\uB294 \uC774 \uC601\uC5ED\uC5D0\uC11C \uAE30\uC900\uC774 \uC5C4\uACA9\uD558\uAC8C \uB290\uAEF4\uC9C0\uC9C0\uB9CC, \uBB35\uBB35\uD788 \uB2E8\uB828\uD560\uC218\uB85D \uC911\uBC18 \uC774\uD6C4 \uAC00\uC7A5 \uB2E8\uB2E8\uD55C \uC804\uBB38\uC131\uACFC \uAD8C\uC704\uB85C \uBCF4\uB2F5\uBC1B\uC2B5\uB2C8\uB2E4.`;
      break;
    case "rahu":
      interpretation = `\uC774\uBC88 \uC0DD\uC758 \uD655\uC7A5\uACFC \uC5F4\uB9DD\uC744 \uAC00\uB9AC\uD0A4\uB294 \uB77C\uD6C4(\uBD81\uAD50\uC810)\uAC00 ${sign.sanskritKo}(${sign.nameKo}) \xB7 ${houseDomain}\uC5D0 \uBA38\uBB3C\uB7EC \uC788\uC2B5\uB2C8\uB2E4. \uC775\uC219\uD558\uC9C0 \uC54A\uC740 \uC0C8 \uC601\uC5ED\uC744 \uACFC\uAC10\uD788 \uD0D0\uD5D8\uD558\uACE0 \uC695\uB9DD\uC744 \uAC74\uC124\uC801 \uC131\uCDE8\uB85C \uBC14\uAFC0 \uB54C \uD070 \uB3C4\uC57D\uC774 \uC77C\uC5B4\uB0A9\uB2C8\uB2E4.`;
      break;
    case "ketu":
      interpretation = `\uD0C0\uACE0\uB09C \uB0B4\uACF5\uACFC \uBE44\uC6C0\uC758 \uC9C0\uD61C\uB97C \uB73B\uD558\uB294 \uCF00\uD22C(\uB0A8\uAD50\uC810)\uAC00 ${sign.sanskritKo}(${sign.nameKo}) \xB7 ${houseDomain}\uC5D0 \uB193\uC600\uC2B5\uB2C8\uB2E4. \uC774\uBBF8 \uC775\uC219\uD558\uACE0 \uC798\uD558\uB294 \uC601\uC5ED\uC774\uBBC0\uB85C \uACFC\uB3C4\uD55C \uC9D1\uCC29\uC744 \uB0B4\uB824\uB193\uC744\uC218\uB85D \uC624\uD788\uB824 \uB9D1\uC740 \uC9C1\uAD00\uACFC \uC644\uC131\uB3C4\uAC00 \uB4DC\uB7EC\uB0A9\uB2C8\uB2E4.`;
      break;
  }
  return {
    id,
    nameKo,
    sanskritKo,
    shortLabel,
    symbol,
    domainKo,
    longitude: lon,
    sign,
    degreeInSign,
    degreeLabel: formatDegree(degreeInSign),
    nakshatra: nak.info,
    pada: nak.pada,
    house,
    houseDomain,
    interpretation
  };
}
function calculateVimshottariDashas(birthYear, birthMonth, birthDay, moonLon) {
  const birthDecimalYear = birthYear + (birthMonth - 1) / 12 + (birthDay - 1) / 365.25;
  const referenceYear = 2026.9;
  const nak = getNakshatraFromLongitude(moonLon);
  const startSeqIdx = nak.info.index % 9;
  const firstEntry = VIMSHOTTARI_SEQUENCE[startSeqIdx];
  const remainingFraction = 1 - nak.fractionElapsed;
  const firstDuration = firstEntry.years * remainingFraction;
  const allPeriods = [];
  let cursor = birthDecimalYear;
  for (let step = 0; step < 12; step++) {
    const seqIdx = (startSeqIdx + step) % 9;
    const item = VIMSHOTTARI_SEQUENCE[seqIdx];
    const dur = step === 0 ? firstDuration : item.years;
    const exactStart = cursor;
    const exactEnd = cursor + dur;
    const isCurrent = referenceYear >= exactStart && referenceYear < exactEnd;
    allPeriods.push({
      lordId: item.lordId,
      lordKo: item.lordKo,
      sanskritKo: item.sanskritKo,
      startYear: Math.floor(exactStart),
      endYear: Math.floor(exactEnd),
      durationYears: Number(dur.toFixed(1)),
      isCurrent,
      theme: item.theme,
      exactStart,
      exactEnd,
      seqIdx
    });
    cursor = exactEnd;
  }
  let currentIdx = allPeriods.findIndex((p) => p.isCurrent);
  if (currentIdx === -1) {
    currentIdx = referenceYear < birthDecimalYear ? 0 : Math.min(allPeriods.length - 1, 5);
    allPeriods[currentIdx].isCurrent = true;
  }
  const currentMaha = allPeriods[currentIdx];
  const mahaFullYears = VIMSHOTTARI_SEQUENCE[currentMaha.seqIdx].years;
  const mahaVirtualStart = currentMaha.exactEnd - mahaFullYears;
  let antarCursor = mahaVirtualStart;
  let activeAntar = VIMSHOTTARI_SEQUENCE[currentMaha.seqIdx];
  let activeAntarEnd = currentMaha.exactEnd;
  for (let k = 0; k < 9; k++) {
    const aIdx = (currentMaha.seqIdx + k) % 9;
    const aItem = VIMSHOTTARI_SEQUENCE[aIdx];
    const aDur = mahaFullYears * aItem.years / 120;
    const aEnd = antarCursor + aDur;
    if (referenceYear >= antarCursor && referenceYear < aEnd) {
      activeAntar = aItem;
      activeAntarEnd = aEnd;
      break;
    }
    antarCursor = aEnd;
  }
  const endYearInt = Math.floor(activeAntarEnd);
  const endMonthInt = Math.max(1, Math.min(12, Math.round((activeAntarEnd - endYearInt) * 12) + 1));
  const windowStart = Math.max(0, Math.min(currentIdx - 1, allPeriods.length - 5));
  const timeline = allPeriods.slice(windowStart, windowStart + 5).map(({ exactStart: _s, exactEnd: _e, seqIdx: _i, ...rest }) => rest);
  const { exactStart: _cs, exactEnd: _ce, seqIdx: _ci, ...cleanCurrent } = currentMaha;
  return {
    currentMahadasha: cleanCurrent,
    currentAntardasha: {
      lordKo: activeAntar.lordKo,
      sanskritKo: activeAntar.sanskritKo,
      endYearMonth: `${endYearInt}\uB144 ${endMonthInt}\uC6D4\uACBD\uAE4C\uC9C0`,
      theme: activeAntar.theme
    },
    timeline
  };
}
function buildCrossInsight(saju, moon, sun, lagna, rahu, ketu, dominantTattva, currentMaha) {
  const strongestSaju = [...saju.elementBalance].sort(
    (a, b) => b.weightedScore - a.weightedScore
  )[0];
  const sajuActive = strongestSaju.element === "wood" || strongestSaju.element === "fire";
  const vedicActive = dominantTattva.element === "fire" || dominantTattva.element === "air";
  const sajuGrounded = strongestSaju.element === "earth" || strongestSaju.element === "metal";
  const vedicGrounded = dominantTattva.element === "earth";
  const sajuDeep = strongestSaju.element === "water";
  const vedicDeep = dominantTattva.element === "water";
  let headline = "";
  let sharedTheme = "";
  let contrastNote = "";
  if (sajuActive && vedicActive || sajuGrounded && vedicGrounded || sajuDeep && vedicDeep) {
    headline = `\uBA85\uB9AC\uC758 ${strongestSaju.hangul}(${strongestSaju.hanja}) \uAE30\uC6B4\uACFC \uBCA0\uB515\uC758 ${dominantTattva.nameKo} \uC6D0\uC18C\uAC00 \uD55C \uACB0\uB85C \uB9DE\uBB3C\uB9AC\uB294 \uC120\uBA85\uD55C \uBA85\uC2DD`;
    sharedTheme = `\uC0AC\uC8FC \uC6D0\uAD6D\uC5D0\uC11C ${strongestSaju.hangul}(${strongestSaju.hanja})\uC774 ${strongestSaju.percentage}%\uB85C \uC8FC\uB3C4\uAD8C\uC744 \uC950\uACE0 \uC788\uC73C\uBA70, \uD56D\uC131\uD669\uB3C4 \uBCA0\uB515 \uCFE4\uB2EC\uB9AC\uC5D0\uC11C\uB3C4 ${dominantTattva.nameKo} \uC6D0\uC18C\uAC00 ${dominantTattva.percentage}%\uB85C \uAC00\uC7A5 \uAC15\uD558\uAC8C \uC791\uB3D9\uD569\uB2C8\uB2E4. \uCD9C\uC0DD \uB2EC \uB098\uD06C\uC0E4\uD2B8\uB77C '${moon.nakshatra.nameKo}'(${moon.pada}\uD30C\uB2E4)\uC758 \uAE30\uC9C8\uAE4C\uC9C0 \uAC19\uC740 \uBC29\uD5A5\uC744 \uAC00\uB9AC\uCF1C, \uC2A4\uC2A4\uB85C \uB0A9\uB4DD\uD55C \uBAA9\uD45C\uC5D0 \uC9D1\uC911\uD560 \uB54C \uC5D0\uB108\uC9C0 \uB204\uC218\uAC00 \uC801\uC2B5\uB2C8\uB2E4.`;
    contrastNote = `\uB450 \uCCB4\uACC4 \uBAA8\uB450 \uAC19\uC740 \uACB0\uC744 \uC99D\uD3ED\uC2DC\uD0A4\uACE0 \uC788\uC73C\uBBC0\uB85C, \uC0AC\uC8FC \uADE0\uD615 \uC6A9\uC2E0\uC778 ${ELEMENT_META[saju.yongsin.primary].hangul}(${ELEMENT_META[saju.yongsin.primary].hanja})\uACFC \uB77C\uD6C4(${rahu.sign.sanskritKo} \xB7 ${rahu.house}\uD558\uC6B0\uC2A4)\uAC00 \uAC00\uB9AC\uD0A4\uB294 \uC0C8\uB85C\uC6B4 \uC2DC\uB3C4\uB97C \uACC1\uB4E4\uC77C \uB54C \uCE58\uC6B0\uCE68 \uC5C6\uB294 \uC785\uCCB4\uAC10\uC774 \uC644\uC131\uB429\uB2C8\uB2E4.`;
  } else {
    headline = `\uC0AC\uC8FC '${saju.pillars.day.ganjiHangul}\uC77C\uC8FC'\uC758 \uBF08\uB300 \uC704\uC5D0 \uCC2C\uB4DC\uB77C '${moon.sign.sanskritKo}(${moon.sign.nameKo}) \xB7 ${moon.nakshatra.nameKo}'\uC758 \uAE4A\uC774\uAC00 \uACB9\uCE58\uB294 \uC785\uCCB4 \uBA85\uC2DD`;
    sharedTheme = `\uB3D9\uC591 \uB9CC\uC138\uB825\uC5D0\uC11C\uB294 ${saju.dayMaster.hangul}(${saju.dayMaster.hanja}) \uC77C\uAC04\uACFC ${saju.gyeokguk.name}\uC744 \uC911\uC2EC\uC73C\uB85C ${strongestSaju.hangul}(${strongestSaju.hanja})\uC758 \uC0C9\uCC44\uAC00 \uB450\uB4DC\uB7EC\uC9C0\uB294 \uBC18\uBA74, \uC778\uB3C4 \uBCA0\uB515 \uC810\uC131\uC220\uC5D0\uC11C\uB294 \uB9C8\uC74C\uC758 \uC911\uC2EC\uC778 \uCC2C\uB4DC\uB77C(\uB2EC)\uAC00 ${moon.sign.sanskritKo}(${moon.sign.nameKo})\uC758 '${moon.nakshatra.nameKo}' \uB098\uD06C\uC0E4\uD2B8\uB77C\uC5D0 \uB193\uC5EC ${dominantTattva.nameKo} \uC6D0\uC18C(${dominantTattva.percentage}%)\uAC00 \uC791\uB3D9\uD569\uB2C8\uB2E4.`;
    contrastNote = `\uC0AC\uC8FC\uC640 \uBCA0\uB515\uC774 \uC11C\uB85C \uB2E4\uB978 \uACB0\uC744 \uBCF4\uC5EC \uC900\uB2E4\uB294 \uAC83\uC740 \uC0C1\uD669\uC5D0 \uB530\uB77C \uAEBC\uB0B4 \uC4F8 \uC218 \uC788\uB294 \uB0B4\uBA74\uC758 \uB3C4\uAD6C\uAC00 \uB450 \uACB9\uC774\uB77C\uB294 \uB73B\uC785\uB2C8\uB2E4. \uC0AC\uD68C\uC801 \uC5ED\uD560\uC5D0\uC11C\uB294 \uC0AC\uC8FC \uACA9\uAD6D(${saju.gyeokguk.name})\uC758 \uBC29\uC2DD\uC774, \uB9C8\uC74C\uC758 \uD734\uC2DD\uACFC \uC9C1\uAD00\uC5D0\uC11C\uB294 '${moon.nakshatra.nameKo}' \uB098\uD06C\uC0E4\uD2B8\uB77C\uC758 \uAC10\uAC01\uC774 \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uAE38\uC7A1\uC774\uAC00 \uB429\uB2C8\uB2E4.`;
  }
  return {
    headline,
    sharedTheme,
    contrastNote,
    synthesisPoints: [
      {
        label: "\uBCF8\uC131\uACFC \uB9C8\uC74C\uC758 \uBCC4 (\uC77C\uAC04 \xD7 \uCC2C\uB4DC\uB77C\xB7\uB098\uD06C\uC0E4\uD2B8\uB77C)",
        content: `\uC0AC\uC8FC \uC77C\uAC04 '${saju.dayMaster.hangul}(${saju.dayMaster.hanja}) \xB7 ${saju.dayMaster.natureTitle}'\uC758 \uBCF8\uC131\uC5D0 \uBCA0\uB515 \uCD9C\uC0DD \uB2EC '${moon.sign.sanskritKo}(${moon.sign.nameKo}) \xB7 ${moon.nakshatra.nameKo}(${moon.nakshatra.keyword})'\uC758 \uC815\uC11C \uB9AC\uB4EC\uC774 \uD3EC\uAC1C\uC838 \uACE0\uC720\uD55C \uB0B4\uBA74\uC744 \uC774\uB8F9\uB2C8\uB2E4.`
      },
      {
        label: "\uB4DC\uB7EC\uB098\uB294 \uD0DC\uB3C4 (\uACA9\uAD6D \xD7 \uB77C\uADF8\uB098\xB7\uD0DC\uC591)",
        content: lagna ? `\uC0AC\uC8FC '${saju.gyeokguk.name}'\uC758 \uC0AC\uD68C\uC801 \uC5ED\uD560\uC5D0 \uC0C1\uC2B9\uAD81 \uB77C\uADF8\uB098 '${lagna.sign.sanskritKo}(${lagna.sign.nameKo})'\uC758 \uCCAB\uC778\uC0C1\uACFC \uC218\uB9AC\uC57C(\uD0DC\uC591) '${sun.sign.sanskritKo}'\uC758 \uC758\uC9C0\uAC00 \uB354\uD574\uC838 \uC138\uC0C1\uACFC \uB9CC\uB098\uB294 \uBC29\uC2DD\uC744 \uB9CC\uB4ED\uB2C8\uB2E4.` : `\uC0AC\uC8FC '${saju.gyeokguk.name}'\uC758 \uC0AC\uD68C\uC801 \uC5ED\uD560\uC5D0 \uC218\uB9AC\uC57C(\uD0DC\uC591) '${sun.sign.sanskritKo}(${sun.sign.nameKo})'\uC758 \uC758\uC9C0\uAC00 \uB354\uD574\uC838 \uB300\uC678\uC801 \uC874\uC7AC\uAC10\uC744 \uC138\uC6C1\uB2C8\uB2E4.`
      },
      {
        label: "\uC774\uBC88 \uC0DD\uC758 \uC131\uC7A5\uCD95 (\uC6A9\uC2E0 \xD7 \uB77C\uD6C4\xB7\uCF00\uD22C)",
        content: `\uBA85\uC2DD\uC758 \uADE0\uD615\uC744 \uC5EC\uB294 \uC6A9\uC2E0 ${ELEMENT_META[saju.yongsin.primary].hangul}(${ELEMENT_META[saju.yongsin.primary].hanja})\uACFC \uD568\uAED8, \uBCA0\uB515 \uB77C\uD6C4(${rahu.house}\uD558\uC6B0\uC2A4 \xB7 ${rahu.sign.sanskritKo})\uAC00 \uB3C4\uC804\uD560 \uBB34\uB300\uB97C, \uCF00\uD22C(${ketu.house}\uD558\uC6B0\uC2A4 \xB7 ${ketu.sign.sanskritKo})\uAC00 \uB0B4\uB824\uB193\uC744 \uC9D1\uCC29\uC744 \uC9DA\uC5B4 \uC90D\uB2C8\uB2E4.`
      }
    ],
    seoldamQuote: `\uB3D9\uC591\uC758 \uB9CC\uC138\uB825\uACFC \uC778\uB3C4\uC758 \uD56D\uC131 \uCFE4\uB2EC\uB9AC\uB97C \uB098\uB780\uD788 \uD3BC\uCCD0 \uBCF4\uB2C8 \uACB0\uC774 \uCC38 \uAE4A\uAD70\uC694. \uC0AC\uC8FC\uB85C\uB294 ${saju.pillars.day.ganjiHangul}\uC77C\uC8FC\uC758 \uBF08\uB300\uAC00, \uBCA0\uB515\uC73C\uB85C\uB294 \u2018${moon.nakshatra.nameKo}\u2019 \uB2EC\uACFC \uD604\uC7AC \uD750\uB974\uB294 ${currentMaha.lordKo}(${currentMaha.sanskritKo}) \uB9C8\uD558\uB2E4\uC0E4\uC758 \uBC15\uC790\uAC00 \uACB9\uCCD0 \uBCF4\uC785\uB2C8\uB2E4. \uB450 \uC9C0\uB3C4\uB97C \uD568\uAED8 \uC0B4\uD53C\uBA70 \uBCF8\uC778\uC758 \uC18D\uB3C4\uB97C \uBBFF\uC5B4 \uBCF4\uC2DC\uAE38 \uBC14\uB78D\uB2C8\uB2E4.`,
    footnote: `24\uC808\uAE30 \uC6D0\uAD6D(${saju.pillars.day.ganjiHanja}) \xD7 \uB77C\uD788\uB9AC \uD56D\uC131\uD669\uB3C4(\uCC2C\uB4DC\uB77C ${moon.sign.sanskritKo} \xB7 ${moon.nakshatra.nameKo} ${moon.pada}\uD30C\uB2E4 \xB7 ${currentMaha.lordKo} \uB300\uC6B4)`
  };
}
function calculateAstrologyChart(saju) {
  const { year, month, day, hour, minute } = saju.solarDate;
  const jd = getJulianDayFromUtc(year, month, day, hour, minute);
  const lons = calculateSiderealLongitudes(jd);
  const moonSignIdx = Math.floor(norm360(lons.moon) / 30) % 12;
  const lagnaSignIdx = Math.floor(norm360(lons.lagna) / 30) % 12;
  const chartBase = saju.input.unknownTime ? "chandra" : "lagna";
  const baseRashiIndex = chartBase === "lagna" ? lagnaSignIdx : moonSignIdx;
  const lagna = saju.input.unknownTime ? null : buildGrahaPlacement(
    "lagna",
    "\uB77C\uADF8\uB098(\uC0C1\uC2B9\uAD81)",
    "Lagna",
    "\uB77C\uADF8\uB098",
    "ASC",
    "\uC0B6\uC758 \uCD9C\uBC1C\uC810 \xB7 \uCCAB\uC778\uC0C1",
    lons.lagna,
    baseRashiIndex
  );
  const moon = buildGrahaPlacement(
    "moon",
    "\uB2EC",
    "Chandra \xB7 \uCC2C\uB4DC\uB77C",
    "\uB2EC",
    "\u263D",
    "\uB9C8\uC74C \xB7 \uC815\uC11C \xB7 \uCD9C\uC0DD \uB098\uD06C\uC0E4\uD2B8\uB77C",
    lons.moon,
    baseRashiIndex
  );
  const sun = buildGrahaPlacement(
    "sun",
    "\uD0DC\uC591",
    "Surya \xB7 \uC218\uB9AC\uC57C",
    "\uD0DC\uC591",
    "\u2609",
    "\uC601\uD63C \xB7 \uC790\uC874\uAC10 \xB7 \uBA85\uBD84",
    lons.sun,
    baseRashiIndex
  );
  const mars = buildGrahaPlacement(
    "mars",
    "\uD654\uC131",
    "Mangala \xB7 \uB9DD\uAC08\uB77C",
    "\uD654\uC131",
    "\u2642",
    "\uC6A9\uAE30 \xB7 \uC2E4\uD589 \uC5D0\uB108\uC9C0",
    lons.mars,
    baseRashiIndex
  );
  const mercury = buildGrahaPlacement(
    "mercury",
    "\uC218\uC131",
    "Budha \xB7 \uBD80\uB2E4",
    "\uC218\uC131",
    "\u263F",
    "\uC9C0\uC131 \xB7 \uC5B8\uC5B4 \xB7 \uC2E4\uBB34 \uAC10\uAC01",
    lons.mercury,
    baseRashiIndex
  );
  const jupiter = buildGrahaPlacement(
    "jupiter",
    "\uBAA9\uC131",
    "Guru \xB7 \uAD6C\uB8E8",
    "\uBAA9\uC131",
    "\u2643",
    "\uC9C0\uD61C \xB7 \uD655\uC7A5 \xB7 \uADC0\uC778\uC758 \uBCF5",
    lons.jupiter,
    baseRashiIndex
  );
  const venus = buildGrahaPlacement(
    "venus",
    "\uAE08\uC131",
    "Shukra \xB7 \uC288\uD06C\uB77C",
    "\uAE08\uC131",
    "\u2640",
    "\uC0AC\uB791 \xB7 \uC2EC\uBBF8\uC548 \xB7 \uD48D\uC694",
    lons.venus,
    baseRashiIndex
  );
  const saturn = buildGrahaPlacement(
    "saturn",
    "\uD1A0\uC131",
    "Shani \xB7 \uC0E4\uB2C8",
    "\uD1A0\uC131",
    "\u2644",
    "\uCC45\uC784 \xB7 \uADDC\uC728 \xB7 \uC7A5\uAE30 \uC131\uCDE8",
    lons.saturn,
    baseRashiIndex
  );
  const rahu = buildGrahaPlacement(
    "rahu",
    "\uB77C\uD6C4",
    "Rahu \xB7 \uBD81\uAD50\uC810",
    "\uB77C\uD6C4",
    "\u260A",
    "\uC774\uBC88 \uC0DD\uC758 \uD655\uC7A5 \xB7 \uC5F4\uB9DD\uCD95",
    lons.rahu,
    baseRashiIndex
  );
  const ketu = buildGrahaPlacement(
    "ketu",
    "\uCF00\uD22C",
    "Ketu \xB7 \uB0A8\uAD50\uC810",
    "\uCF00\uD22C",
    "\u260B",
    "\uD0C0\uACE0\uB09C \uB0B4\uACF5 \xB7 \uBE44\uC6C0\uC758 \uC9C0\uD61C",
    lons.ketu,
    baseRashiIndex
  );
  const placements = [
    ...lagna ? [lagna] : [],
    moon,
    sun,
    mars,
    mercury,
    jupiter,
    venus,
    saturn,
    rahu,
    ketu
  ];
  const elCounts = { fire: 0, earth: 0, air: 0, water: 0 };
  const elWeights = { fire: 0, earth: 0, air: 0, water: 0 };
  for (const p of placements) {
    const w = p.id === "moon" || p.id === "lagna" ? 1.5 : p.id === "rahu" || p.id === "ketu" ? 0.75 : 1;
    elCounts[p.sign.element] += 1;
    elWeights[p.sign.element] += w;
  }
  const totalElW = Object.values(elWeights).reduce((a, b) => a + b, 0) || 1;
  const elements = ["fire", "earth", "air", "water"].map(
    (el) => ({
      element: el,
      nameKo: VEDIC_ELEMENT_META[el].nameKo,
      count: elCounts[el],
      percentage: Math.round(elWeights[el] / totalElW * 100),
      color: VEDIC_ELEMENT_META[el].color
    })
  );
  const dominantElement = [...elements].sort((a, b) => b.percentage - a.percentage)[0];
  const dashas = calculateVimshottariDashas(year, month, day, lons.moon);
  const rahuKetuAxis = {
    rahuSign: rahu.sign,
    ketuSign: ketu.sign,
    rahuHouse: rahu.house,
    ketuHouse: ketu.house,
    headline: `\uB77C\uD6C4 ${rahu.sign.sanskritKo}(${rahu.house}\uD558\uC6B0\uC2A4) \u2194 \uCF00\uD22C ${ketu.sign.sanskritKo}(${ketu.house}\uD558\uC6B0\uC2A4) \uCE74\uB974\uB9C8 \uCD95`,
    rahuGuidance: `\uC774\uBC88 \uC0DD\uC5D0\uC11C \uC0C8\uB86D\uAC8C \uB113\uD600 \uAC00\uC57C \uD560 \uBB34\uB300\uB294 '${rahu.houseDomain}'\uACFC ${rahu.sign.sanskritKo}(${rahu.sign.nameKo})\uC758 '${rahu.sign.keyword}'\uC785\uB2C8\uB2E4. \uB2E4\uC18C \uB0AF\uC124\uACE0 \uC695\uC2EC\uC774 \uC0DD\uAE30\uB294 \uC601\uC5ED\uC774\uC9C0\uB9CC \uC815\uBA74\uC73C\uB85C \uBC30\uC6CC \uB098\uAC08 \uB54C \uAC00\uC7A5 \uD070 \uC131\uC7A5\uC774 \uC5F4\uB9BD\uB2C8\uB2E4.`,
    ketuGuidance: `\uBC18\uB300\uD3B8 '${ketu.houseDomain}'\uACFC ${ketu.sign.sanskritKo}(${ketu.sign.nameKo})\uB294 \uC774\uBBF8 \uB0B4\uACF5\uC774 \uCD95\uC801\uB41C \uC790\uB9AC\uC785\uB2C8\uB2E4. \uC9C0\uB098\uCE5C \uC9D1\uCC29\uC774\uB098 \uC644\uBCBD\uC8FC\uC758\uB97C \uB0B4\uB824\uB193\uACE0 \uB2F4\uBC31\uD558\uAC8C \uD65C\uC6A9\uD560\uC218\uB85D \uBCF8\uC5F0\uC758 \uC9C1\uAD00\uC774 \uB9D1\uAC8C \uBE5B\uB0A9\uB2C8\uB2E4.`
  };
  const crossInsight = buildCrossInsight(
    saju,
    moon,
    sun,
    lagna,
    rahu,
    ketu,
    dominantElement,
    dashas.currentMahadasha
  );
  return {
    ayanamsaDeg: Number(lons.ayanamsa.toFixed(2)),
    ayanamsaLabel: `\uB77C\uD788\uB9AC \uC544\uC57C\uB0A8\uC0AC ${formatDegree(lons.ayanamsa)}`,
    chartBase,
    baseRashiIndex,
    placements,
    lagna,
    moon,
    sun,
    mars,
    mercury,
    jupiter,
    venus,
    saturn,
    rahu,
    ketu,
    janmaNakshatra: {
      info: moon.nakshatra,
      pada: moon.pada,
      padaFocus: PADA_FOCUS[moon.pada] ?? PADA_FOCUS[1]
    },
    dashas,
    rahuKetuAxis,
    elements,
    dominantElement,
    crossInsight
  };
}

// server/engine/annualFortune.ts
var CHEONEUL_BRANCHES = {
  0: [1, 7],
  4: [1, 7],
  6: [1, 7],
  1: [0, 8],
  5: [0, 8],
  2: [11, 9],
  3: [11, 9],
  7: [2, 6],
  8: [3, 5],
  9: [3, 5]
};
function detectYearInteractions(chart, yearStemIdx, yearBranchIdx) {
  const pillars = [
    chart.pillars.year,
    chart.pillars.month,
    chart.pillars.day,
    ...chart.pillars.hour ? [chart.pillars.hour] : []
  ];
  const notes = [];
  const seen = /* @__PURE__ */ new Set();
  const stemCombinePairs = [
    [0, 5, "\uAC11\uAE30\uD569(\u7532\u5DF1\u5408)"],
    [1, 6, "\uC744\uACBD\uD569(\u4E59\u5E9A\u5408)"],
    [2, 7, "\uBCD1\uC2E0\uD569(\u4E19\u8F9B\u5408)"],
    [3, 8, "\uC815\uC784\uD569(\u4E01\u58EC\u5408)"],
    [4, 9, "\uBB34\uACC4\uD569(\u620A\u7678\u5408)"]
  ];
  const branchCombinePairs = [
    [0, 1, "\uC790\uCD95\uD569(\u5B50\u4E11\u5408)"],
    [2, 11, "\uC778\uD574\uD569(\u5BC5\u4EA5\u5408)"],
    [3, 10, "\uBB18\uC220\uD569(\u536F\u620C\u5408)"],
    [4, 9, "\uC9C4\uC720\uD569(\u8FB0\u9149\u5408)"],
    [5, 8, "\uC0AC\uC2E0\uD569(\u5DF3\u7533\u5408)"],
    [6, 7, "\uC624\uBBF8\uD569(\u5348\u672A\u5408)"]
  ];
  const branchClashPairs = [
    [0, 6, "\uC790\uC624\uCDA9(\u5B50\u5348\u6C96)"],
    [1, 7, "\uCD95\uBBF8\uCDA9(\u4E11\u672A\u6C96)"],
    [2, 8, "\uC778\uC2E0\uCDA9(\u5BC5\u7533\u6C96)"],
    [3, 9, "\uBB18\uC720\uCDA9(\u536F\u9149\u6C96)"],
    [4, 10, "\uC9C4\uC220\uCDA9(\u8FB0\u620C\u6C96)"],
    [5, 11, "\uC0AC\uD574\uCDA9(\u5DF3\u4EA5\u6C96)"]
  ];
  for (const p of pillars) {
    for (const [s1, s2, label] of stemCombinePairs) {
      if (yearStemIdx === s1 && p.stem.index === s2 || yearStemIdx === s2 && p.stem.index === s1) {
        const key = `sc-${label}-${p.position}`;
        if (!seen.has(key)) {
          seen.add(key);
          notes.push(`${p.label} \uCC9C\uAC04\uACFC ${label}`);
        }
      }
    }
    for (const [b1, b2, label] of branchCombinePairs) {
      if (yearBranchIdx === b1 && p.branch.index === b2 || yearBranchIdx === b2 && p.branch.index === b1) {
        const key = `bc-${label}-${p.position}`;
        if (!seen.has(key)) {
          seen.add(key);
          notes.push(`${p.label} \uC9C0\uC9C0\uC640 ${label}`);
        }
      }
    }
    for (const [b1, b2, label] of branchClashPairs) {
      if (yearBranchIdx === b1 && p.branch.index === b2 || yearBranchIdx === b2 && p.branch.index === b1) {
        const key = `ch-${label}-${p.position}`;
        if (!seen.has(key)) {
          seen.add(key);
          notes.push(`${p.label} \uC9C0\uC9C0\uC640 ${label}`);
        }
      }
    }
  }
  if (yearBranchIdx === 6 && pillars.some((p) => p.branch.index === 6)) {
    notes.push("\uC6D0\uAD6D \uC624(\u5348)\uC640 \uC624\uC624\uC790\uD615(\u5348\u5348\u81EA\u5211)");
  }
  return notes.slice(0, 3);
}
function buildYearSummary(chart, year, stemIdx, branchIdx, nickname) {
  const stem = STEMS[stemIdx];
  const branch = BRANCHES[branchIdx];
  const mainHidden = STEMS[branch.hiddenStems[branch.hiddenStems.length - 1]];
  const stemTenGod = getTenGod(chart.dayMaster, stem);
  const branchTenGod = getTenGod(chart.dayMaster, mainHidden);
  const lifeStage = getLifeStage(chart.dayMaster, branchIdx);
  const yong = chart.yongsin.primary;
  const secondary = chart.yongsin.secondary;
  const isYongsinYear = stem.element === yong || branch.element === yong || stem.element === secondary || branch.element === secondary;
  const isCheoneulYear = CHEONEUL_BRANCHES[chart.dayMaster.index].includes(branchIdx);
  const interactionsWithChart = detectYearInteractions(chart, stemIdx, branchIdx);
  return {
    year,
    ganjiHangul: `${stem.hangul}${branch.hangul}`,
    ganjiHanja: `${stem.hanja}${branch.hanja}`,
    nickname,
    stem,
    branch,
    stemTenGod,
    branchTenGod,
    lifeStage,
    isYongsinYear,
    isCheoneulYear,
    interactionsWithChart
  };
}
