    index: "03",
    title: "\uC7AC\uBB3C \uBC0F \uAE08\uC804\uC6B4",
    subtitle: "\uB3C8\uC774 \uB4E4\uC5B4\uC624\uB294 \uD1B5\uB85C, \uC9C0\uD0A4\uB294 \uD798, \uADF8\uB9AC\uACE0 \uB9AC\uC2A4\uD06C \uAD00\uB9AC",
    evidenceLine: `\uC7AC\uC131 ${jaeseongPct}% \xB7 \uC2DD\uC0C1 ${siksangPct}% \xB7 \uBE44\uAC81 ${bigeopPct}% \xB7 ${hasStorageBranch ? "\uCC3D\uACE0\uC9C0(\u8FB0\u620C\u4E11\u672A) \uBCF4\uC720" : "\uC720\uB3D9 \uC21C\uD658\uD615"}`,
