        description: `${fromName}\uB2D8\uC774 ${toName}\uB2D8\uC758 \uB2E8\uC815\uD55C \uD0DC\uB3C4\uC640 \uD310\uB2E8\uB825\uC5D0 \uC2E0\uB8B0\uB97C \uB290\uB08D\uB2C8\uB2E4. \uD754\uB4E4\uB9B4 \uB54C \uC911\uC2EC\uC744 \uC7A1\uC544\uC8FC\uB294 \uACE0\uB9C8\uC6B4 \uAE30\uC900\uC810 \uC5ED\uD560\uC744 \uD574\uC90D\uB2C8\uB2E4.`
