        description: `${fromName}\uB2D8\uC774 ${toName}\uB2D8\uC758 \uC0C9\uB2E4\uB978 \uAD00\uC810\uC5D0\uC11C \uC601\uAC10\uC744 \uBC1B\uC2B5\uB2C8\uB2E4. \uC11C\uB85C\uC758 \uAC1C\uC778 \uC2DC\uAC04\uC744 \uC874\uC911\uD560 \uB54C \uAE4A\uC740 \uC9C0\uC801\uC778 \uAD50\uAC10\uC774 \uC774\uB8E8\uC5B4\uC9D1\uB2C8\uB2E4.`
