        description: `${fromName}\uB2D8\uC774 ${toName}\uB2D8 \uACC1\uC5D0\uC11C \uC815\uC11C\uC801\uC778 \uC9C0\uC9C0\uC640 \uD3B8\uC548\uD568\uC744 \uC5BB\uC2B5\uB2C8\uB2E4. \uC870\uC5B8\uC744 \uAD6C\uD558\uAC70\uB098 \uC9C0\uCE60 \uB54C \uBA3C\uC800 \uB5A0\uC62C\uB9AC\uAC8C \uB418\uB294 \uB530\uB73B\uD55C \uC874\uC7AC\uC785\uB2C8\uB2E4.`
